import fs from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { PlatformError } from './platform.mjs';

const UUID = /^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/;
const IMAGE_ID = /^[a-f0-9]{24}$/;
export function requireSnapshotId(id) { if (!UUID.test(id || '')) throw new PlatformError('INVALID_SNAPSHOT', '快照标识不合法'); return id; }
export function requireImageId(id) { if (!IMAGE_ID.test(id || '')) throw new PlatformError('INVALID_IMAGE_ID', '图片标识不合法'); return id; }

/** 每次写入先落临时文件再替换；不自动清理历史资料，达到配额时明确提示管理员。 */
export class Store {
  constructor(config) { this.root = config.dataDirectory; this.limits = config.limits; this.queue = Promise.resolve(); }
  async init() { await fs.mkdir(this.root, { recursive: true }); }
  async transaction(task) {
    const next = this.queue.then(task); this.queue = next.catch(() => {}); return next;
  }
  async usage() {
    let bytes = 0; let snapshots = 0;
    for (const entry of await fs.readdir(this.root, { withFileTypes: true })) {
      if (!entry.isFile() || !/\.(json|bin)$/.test(entry.name)) continue;
      bytes += (await fs.stat(path.join(this.root, entry.name))).size;
      if (UUID.test(entry.name.slice(0, -5))) snapshots += 1;
    }
    return { bytes, snapshots };
  }
  async write(name, bytes, snapshot = false) {
    return this.transaction(async () => {
      const destination = path.join(this.root, name);
      const existing = await fs.stat(destination).catch(() => null);
      const usage = await this.usage();
      if (snapshot && !existing && usage.snapshots >= this.limits.maxSnapshots) throw new PlatformError('CACHE_FULL', '历史快照达到上限，请备份后清理或增加 maxSnapshots');
      if (usage.bytes - (existing?.size || 0) + bytes.length > this.limits.maxCacheBytes) throw new PlatformError('CACHE_FULL', '本地知识缓存已满，请备份清理或增加 maxCacheBytes');
      const temporary = `${destination}.${randomUUID()}.tmp`;
      await fs.writeFile(temporary, bytes);
      try { await fs.rename(temporary, destination); } finally { await fs.unlink(temporary).catch(() => {}); }
    });
  }
  async save(snapshot) { requireSnapshotId(snapshot.id); await this.write(`${snapshot.id}.json`, Buffer.from(JSON.stringify(snapshot)), true); }
  async load(id) {
    requireSnapshotId(id);
    try { return JSON.parse(await fs.readFile(path.join(this.root, `${id}.json`), 'utf8')); }
    catch (error) { if (error.code === 'ENOENT') throw new PlatformError('SNAPSHOT_NOT_FOUND', '历史资料不存在，请确认 data 目录已随项目迁移'); throw error; }
  }
  async image(id) {
    requireImageId(id);
    try {
      const metadata = JSON.parse(await fs.readFile(path.join(this.root, `${id}.image.json`), 'utf8'));
      return { type: metadata.type, bytes: await fs.readFile(path.join(this.root, `${id}.bin`)) };
    } catch (error) { if (error.code === 'ENOENT') return null; throw error; }
  }
  async saveImage(id, image) {
    requireImageId(id);
    await this.write(`${id}.bin`, image.bytes);
    await this.write(`${id}.image.json`, Buffer.from(JSON.stringify({ type: image.type })));
  }
}
