import { PlatformError } from './platform.mjs';

/** 检索并发和发起间隔由服务统一限制，用户停止时能从等待队列移除请求。 */
export class SearchGate {
  constructor(concurrency = 2, interval = 150) { this.concurrency = concurrency; this.interval = interval; this.active = 0; this.nextStart = 0; this.queue = []; this.timer = null; }
  run(signal, task) {
    signal?.throwIfAborted();
    if (this.queue.length >= 20) return Promise.reject(new PlatformError('SERVICE_BUSY', '等待检索的请求过多，请稍后重试'));
    return new Promise((resolve, reject) => {
      const item = { signal, task, resolve, reject, abort: null };
      item.abort = () => { const index = this.queue.indexOf(item); if (index >= 0) { this.queue.splice(index, 1); reject(signal.reason); } };
      signal?.addEventListener('abort', item.abort, { once: true }); this.queue.push(item); this.drain();
    });
  }
  drain() {
    if (this.timer || this.active >= this.concurrency || !this.queue.length) return;
    const delay = Math.max(0, this.nextStart - Date.now());
    if (delay) { this.timer = setTimeout(() => { this.timer = null; this.drain(); }, delay); return; }
    const item = this.queue.shift(); item.signal?.removeEventListener('abort', item.abort);
    if (item.signal?.aborted) { item.reject(item.signal.reason); this.drain(); return; }
    this.active++; this.nextStart = Date.now() + this.interval;
    Promise.resolve().then(item.task).then(item.resolve, item.reject).finally(() => { this.active--; this.drain(); });
    this.drain();
  }
}
